export class MemeNavigation{constructor(){this.loading=false;this.prefetchedMeme=null;this.transitionDuration=300;this.init();}init(){console.log('[MemeNavigation] Initializing AJAX navigation...');this.bindKeyboardShortcuts();this.bindNavigationButtons();this.setupPopStateHandler();this.prefetchNext();}bindKeyboardShortcuts(){document.addEventListener('keydown',(e)=> this.handleKeyPress(e));}bindNavigationButtons(){const nextButtons=document.querySelectorAll('[data-action="next-meme"],.next-button,#next-btn');nextButtons.forEach(btn=>{btn.addEventListener('click',(e)=>{e.preventDefault();this.loadNextMeme();});});const similarButtons=document.querySelectorAll('[data-action="similar-meme"]');similarButtons.forEach(btn=>{btn.addEventListener('click',(e)=>{e.preventDefault();const subreddit=btn.dataset.subreddit;if(subreddit){this.loadSimilarMeme(subreddit);}});});}setupPopStateHandler(){window.addEventListener('popstate',(event)=>{if(event.state && event.state.meme){this.renderMeme(event.state.meme,false);}else{window.location.reload();}});}handleKeyPress(event){if(this.isInputFocused()){return;}switch(event.code){case 'Space':case 'ArrowRight':event.preventDefault();this.loadNextMeme();break;case 'ArrowLeft':event.preventDefault();window.history.back();break;case 'KeyL':event.preventDefault();this.triggerLike();break;case 'KeyS':event.preventDefault();this.triggerSave();break;case 'KeyT':event.preventDefault();this.toggleTitle();break;}}isInputFocused(){const activeElement=document.activeElement;return activeElement &&(activeElement.tagName==='INPUT' || activeElement.tagName==='TEXTAREA' || activeElement.isContentEditable);}async loadNextMeme(){if(this.loading){console.log('[MemeNavigation] Already loading,please wait...');return;}console.log('[MemeNavigation] Loading next meme via AJAX...');this.loading=true;try{this.showLoadingState();let meme;if(this.prefetchedMeme){console.log('[MemeNavigation] Using prefetched meme');meme=this.prefetchedMeme;this.prefetchedMeme=null;}else{const response=await fetch('/random.json');if(!response.ok){throw new Error(`HTTP ${response.status}:${response.statusText}`);}meme=await response.json();}await this.renderMeme(meme);this.updateURL(meme);this.prefetchNext();this.trackView(meme);console.log('[MemeNavigation] ✅ Meme loaded successfully');}catch(error){console.error('[MemeNavigation] Failed to load meme:',error);this.showError('Failed to load meme. Please try again.');setTimeout(()=>{window.location.href='/random';},2000);}finally{this.loading=false;this.hideLoadingState();}}async loadSimilarMeme(subreddit){if(this.loading)return;console.log(`[MemeNavigation] Loading similar meme from r/${subreddit}...`);this.loading=true;try{this.showLoadingState();const response=await fetch(`/similar.json?subreddit=${encodeURIComponent(subreddit)}`);if(!response.ok){throw new Error(`HTTP ${response.status}`);}const meme=await response.json();await this.renderMeme(meme);this.updateURL(meme);this.prefetchNext();this.trackView(meme);}catch(error){console.error('[MemeNavigation] Failed to load similar meme:',error);this.showError('No similar memes found. Showing random instead.');setTimeout(()=> this.loadNextMeme(),1000);}finally{this.loading=false;this.hideLoadingState();}}async renderMeme(meme,pushState=true){const display=document.querySelector('#meme-display');const info=document.querySelector('#meme-info');if(!display){console.error('[MemeNavigation] #meme-display not found');return;}display.style.opacity='0';display.style.transition=`opacity ${this.transitionDuration}ms ease-out`;await this.wait(this.transitionDuration);display.innerHTML=this.renderMemeHTML(meme);if(info){info.innerHTML=this.renderInfoHTML(meme);}this.updateControlsState(meme);display.style.opacity='1';if(pushState){this.updateURL(meme);}window.scrollTo({top:0,behavior:'smooth'});}renderMemeHTML(meme){if(meme.media_type==='video' || meme.url?.includes('v.redd.it')){return ` <div class="meme-video-container"> <video src="${this.escapeHtml(meme.url)}" controls autoplay loop playsinline class="meme-video" > Your browser doesn't support video playback. </video> </div> `;}if(meme.is_gallery && meme.gallery_images?.length > 0){return this.renderGalleryHTML(meme.gallery_images,meme.title);}return ` <div class="meme-image-container"> <img src="${this.escapeHtml(meme.url)}" alt="${this.escapeHtml(meme.title || 'Meme')}" class="meme-image" loading="eager" onerror="this.src='/images/meme-placeholder.svg'" /> </div> `;}renderGalleryHTML(images,title){const imageElements=images.map((img,index)=> ` <div class="gallery-slide" data-index="${index}"> <img src="${this.escapeHtml(img.url || img)}" alt="${this.escapeHtml(title)}- Image ${index + 1}" class="gallery-image" loading="${index===0 ? 'eager':'lazy'}" /> </div> `).join('');return ` <div class="meme-gallery"> <div class="gallery-container"> ${imageElements}</div> <div class="gallery-controls"> <button class="gallery-prev" onclick="window.memeApp?.navigation?.prevGalleryImage()">‹</button> <span class="gallery-counter">1 / ${images.length}</span> <button class="gallery-next" onclick="window.memeApp?.navigation?.nextGalleryImage()">›</button> </div> </div> `;}renderInfoHTML(meme){const subreddit=this.escapeHtml(meme.subreddit || 'unknown');const title=this.escapeHtml(meme.title || 'Untitled Meme');const likes=parseInt(meme.likes)|| 0;const poolType=meme.diversity_pool || meme.selection_method || 'random';return ` <h2 class="meme-title">${title}</h2> <div class="meme-meta"> <span class="meme-subreddit"> <a href="/category/${subreddit}" title="View more from r/${subreddit}"> r/${subreddit}</a> </span> <span class="meme-divider">•</span> <span class="meme-likes">${likes}likes</span> ${poolType !=='random' ? ` <span class="meme-divider">•</span> <span class="meme-pool-type badge">${poolType}</span> `:''}</div> ${meme.total_unseen ? ` <div class="memes-remaining"> <small>${meme.total_unseen}fresh memes remaining</small> </div> `:''}`;}updateControlsState(meme){const likeBtn=document.querySelector('.like-button');if(likeBtn){likeBtn.classList.remove('liked');likeBtn.dataset.memeUrl=meme.url;}const likeCount=document.querySelector('.like-count');if(likeCount){likeCount.textContent=meme.likes || 0;}const saveBtn=document.querySelector('.save-button');if(saveBtn){saveBtn.classList.remove('saved');saveBtn.dataset.memeUrl=meme.url;}}showLoadingState(){const display=document.querySelector('#meme-display');if(display){display.classList.add('loading');}const controls=document.querySelectorAll('.meme-controls button');controls.forEach(btn=> btn.disabled=true);}hideLoadingState(){const display=document.querySelector('#meme-display');if(display){display.classList.remove('loading');}const controls=document.querySelectorAll('.meme-controls button');controls.forEach(btn=> btn.disabled=false);}showError(message){const display=document.querySelector('#meme-display');if(display){display.innerHTML=` <div class="error-message"> <p>⚠️ ${this.escapeHtml(message)}</p> <button onclick="location.reload()">Reload Page</button> </div> `;}}updateURL(meme){const state={meme:meme};const title=meme.title || 'Random Meme';const url='/random';try{history.pushState(state,title,url);document.title=`${title}- Meme Explorer`;}catch(e){console.warn('[MemeNavigation] Failed to update history:',e);}}prefetchNext(){if(this.loading || this.prefetchedMeme){return;}console.log('[MemeNavigation] Prefetching next meme...');fetch('/random.json').then(response=> response.json()).then(meme=>{this.prefetchedMeme=meme;console.log('[MemeNavigation] ✅ Next meme prefetched');if(meme.url && !meme.url.includes('v.redd.it')){const img=new Image();img.src=meme.url;}}).catch(error=>{console.warn('[MemeNavigation] Prefetch failed:',error);});}trackView(meme){if(typeof gtag !=='undefined'){gtag('event','meme_view',{meme_url:meme.url,subreddit:meme.subreddit,pool_type:meme.diversity_pool || 'random'});}if(typeof window.trackMemeView==='function'){window.trackMemeView(meme);}}toggleTitle(){const titleElement=document.querySelector('.meme-title');if(titleElement){titleElement.style.display=titleElement.style.display==='none' ? 'block':'none';}}triggerLike(){const likeBtn=document.querySelector('.like-button');if(likeBtn)likeBtn.click();}triggerSave(){const saveBtn=document.querySelector('.save-button');if(saveBtn)saveBtn.click();}wait(ms){return new Promise(resolve=> setTimeout(resolve,ms));}escapeHtml(text){const div=document.createElement('div');div.textContent=text;return div.innerHTML;}nextGalleryImage(){const container=document.querySelector('.gallery-container');if(!container)return;const slides=container.querySelectorAll('.gallery-slide');const current=container.querySelector('.gallery-slide.active')|| slides[0];const currentIndex=parseInt(current.dataset.index);const nextIndex=(currentIndex + 1)% slides.length;this.showGallerySlide(nextIndex);}prevGalleryImage(){const container=document.querySelector('.gallery-container');if(!container)return;const slides=container.querySelectorAll('.gallery-slide');const current=container.querySelector('.gallery-slide.active')|| slides[0];const currentIndex=parseInt(current.dataset.index);const prevIndex=currentIndex===0 ? slides.length - 1:currentIndex - 1;this.showGallerySlide(prevIndex);}showGallerySlide(index){const slides=document.querySelectorAll('.gallery-slide');const counter=document.querySelector('.gallery-counter');slides.forEach((slide,i)=>{slide.classList.toggle('active',i===index);});if(counter){counter.textContent=`${index + 1}/ ${slides.length}`;}}}